import{_ as t,o as e,c as i,a5 as l}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"Redis 上线检查清单","description":"本页把开发和运维中最容易遗漏的条件整理成上线前检查项。它不重复讲解机制；每个需要深入判断的项目都链接到对应章节。","frontmatter":{},"headers":[],"relativePath":"redis/04-operations/chapter-08-pitfalls.md","filePath":"redis/04-operations/chapter-08-pitfalls.md"}'),r={name:"redis/04-operations/chapter-08-pitfalls.md"};function s(d,a,c,p,o,n){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="redis-上线检查清单" tabindex="-1" data-src-line="1" data-src-file="redis/04-operations/chapter-08-pitfalls.md">Redis 上线检查清单 <a class="header-anchor" href="#redis-上线检查清单" aria-label="Permalink to &quot;Redis 上线检查清单&quot;">​</a></h1><p data-src-line="3" data-src-file="redis/04-operations/chapter-08-pitfalls.md">本页把开发和运维中最容易遗漏的条件整理成上线前检查项。它不重复讲解机制；每个需要深入判断的项目都链接到对应章节。</p><h2 id="检查开发用法" tabindex="-1" data-src-line="5" data-src-file="redis/04-operations/chapter-08-pitfalls.md">检查开发用法 <a class="header-anchor" href="#检查开发用法" aria-label="Permalink to &quot;检查开发用法&quot;">​</a></h2><h3 id="避免阻塞主线程" tabindex="-1" data-src-line="7" data-src-file="redis/04-operations/chapter-08-pitfalls.md">避免阻塞主线程 <a class="header-anchor" href="#避免阻塞主线程" aria-label="Permalink to &quot;避免阻塞主线程&quot;">​</a></h3><ul data-src-line="9" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="9" data-src-file="redis/04-operations/chapter-08-pitfalls.md">生产查询不使用 <code>KEYS</code>，键空间扫描改用 <code>SCAN</code> 及其迭代版本。</li><li data-src-line="10" data-src-file="redis/04-operations/chapter-08-pitfalls.md">删除大值前先测量大小，优先评估 <code>UNLINK</code> 的后台回收行为。</li><li data-src-line="11" data-src-file="redis/04-operations/chapter-08-pitfalls.md">不一次性读取超大 Hash、List 或 ZSet，按字段或范围分批访问。</li><li data-src-line="12" data-src-file="redis/04-operations/chapter-08-pitfalls.md">客户端使用有上限的连接池，并配置连接超时、读取超时和重试上限。</li></ul><p data-src-line="14" data-src-file="redis/04-operations/chapter-08-pitfalls.md">完整的慢命令判断见<a href="./chapter-04-performance.html">性能优化</a>，大值处理见<a href="./chapter-07-big-hot-key.html">大 Key 与热 Key</a>，连接与重试边界见<a href="./chapter-01-client-connection.html">客户端连接与故障处理</a>。</p><h3 id="选择合适的数据模型" tabindex="-1" data-src-line="16" data-src-file="redis/04-operations/chapter-08-pitfalls.md">选择合适的数据模型 <a class="header-anchor" href="#选择合适的数据模型" aria-label="Permalink to &quot;选择合适的数据模型&quot;">​</a></h3><ul data-src-line="18" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="18" data-src-file="redis/04-operations/chapter-08-pitfalls.md">只更新部分字段时，评估 Hash 是否比整体序列化的 String 更合适。</li><li data-src-line="19" data-src-file="redis/04-operations/chapter-08-pitfalls.md">缓存 Key 明确 TTL、更新路径和淘汰责任，不把缓存当成唯一数据副本。</li><li data-src-line="20" data-src-file="redis/04-operations/chapter-08-pitfalls.md">集合运算、排行榜和位图只在数据规模与命令复杂度可接受时使用。</li><li data-src-line="21" data-src-file="redis/04-operations/chapter-08-pitfalls.md">为业务 Key 定义统一命名、所有权和生命周期，不使用无前缀的临时 Key。</li></ul><p data-src-line="23" data-src-file="redis/04-operations/chapter-08-pitfalls.md">数据类型语义见<a href="./../01-data-model/chapter-02-basic-types.html">五种基础数据类型</a>，缓存失效策略见<a href="./../../scenarios/01-cache/chapter-01-cache-invalidation.html">缓存失效场景</a>。</p><h3 id="检查并发和恢复" tabindex="-1" data-src-line="25" data-src-file="redis/04-operations/chapter-08-pitfalls.md">检查并发和恢复 <a class="header-anchor" href="#检查并发和恢复" aria-label="Permalink to &quot;检查并发和恢复&quot;">​</a></h3><ul data-src-line="27" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="27" data-src-file="redis/04-operations/chapter-08-pitfalls.md">锁具有过期时间、唯一持有者标识和失败重试边界。</li><li data-src-line="28" data-src-file="redis/04-operations/chapter-08-pitfalls.md">任务消费具备确认、重试、幂等和死信处理，不只依赖 <code>BLPOP</code>。</li><li data-src-line="29" data-src-file="redis/04-operations/chapter-08-pitfalls.md">关键写入明确故障时允许丢失的数据量，并据此选择持久化和副本策略。</li><li data-src-line="30" data-src-file="redis/04-operations/chapter-08-pitfalls.md">应用能够处理 <code>LOADING</code>、<code>READONLY</code>、连接拒绝和超时，不进行无上限重试。</li></ul><p data-src-line="32" data-src-file="redis/04-operations/chapter-08-pitfalls.md">锁与限流边界见<a href="./../../scenarios/02-concurrency/">并发控制场景</a>，消息恢复见<a href="./../../scenarios/03-messaging/">消息场景</a>。</p><h2 id="检查运行配置" tabindex="-1" data-src-line="34" data-src-file="redis/04-operations/chapter-08-pitfalls.md">检查运行配置 <a class="header-anchor" href="#检查运行配置" aria-label="Permalink to &quot;检查运行配置&quot;">​</a></h2><h3 id="内存与淘汰" tabindex="-1" data-src-line="36" data-src-file="redis/04-operations/chapter-08-pitfalls.md">内存与淘汰 <a class="header-anchor" href="#内存与淘汰" aria-label="Permalink to &quot;内存与淘汰&quot;">​</a></h3><ul data-src-line="38" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="38" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><code>maxmemory</code> 已扣除操作系统、监控、网络缓冲和 fork/COW 所需空间。</li><li data-src-line="39" data-src-file="redis/04-operations/chapter-08-pitfalls.md">淘汰策略与数据用途一致：可重建缓存可以淘汰，主数据通常使用 <code>noeviction</code> 并扩容。</li><li data-src-line="40" data-src-file="redis/04-operations/chapter-08-pitfalls.md">淘汰次数、内存使用率和碎片率均有告警。</li><li data-src-line="41" data-src-file="redis/04-operations/chapter-08-pitfalls.md">达到 <code>maxmemory</code> 时，应用有明确的降级或拒绝写入行为。</li></ul><p data-src-line="43" data-src-file="redis/04-operations/chapter-08-pitfalls.md">参数含义见<a href="./../reference/parameters.html">配置参数参考</a>，策略边界见<a href="./../02-standalone-core/chapter-06-expiration-eviction.html">过期与淘汰</a>。</p><h3 id="持久化与故障转移" tabindex="-1" data-src-line="45" data-src-file="redis/04-operations/chapter-08-pitfalls.md">持久化与故障转移 <a class="header-anchor" href="#持久化与故障转移" aria-label="Permalink to &quot;持久化与故障转移&quot;">​</a></h3><ul data-src-line="47" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="47" data-src-file="redis/04-operations/chapter-08-pitfalls.md">RDB、AOF 或两者的组合与 RPO 一致，不把“开启持久化”当作数据不丢失的保证。</li><li data-src-line="48" data-src-file="redis/04-operations/chapter-08-pitfalls.md">已完成一次备份恢复和一次从节点数据加载演练。</li><li data-src-line="49" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><code>latest_fork_usec</code>、AOF 重写、磁盘延迟和复制偏移差已纳入监控。</li><li data-src-line="50" data-src-file="redis/04-operations/chapter-08-pitfalls.md">Sentinel 或 Cluster 的故障转移已在非生产环境演练，客户端能够刷新拓扑。</li><li data-src-line="51" data-src-file="redis/04-operations/chapter-08-pitfalls.md">主从默认异步复制的丢失窗口已写入运维文档，并有对应的业务接受结论。</li></ul><p data-src-line="53" data-src-file="redis/04-operations/chapter-08-pitfalls.md">持久化取舍见<a href="./../02-standalone-core/chapter-05-persistence.html">持久化 RDB 与 AOF</a>，备份和恢复流程见<a href="./chapter-03-backup-recovery.html">备份、恢复与升级</a>，拓扑选择见<a href="./../05-practice/chapter-03-first-production.html">首次生产部署</a>。</p><h3 id="网络与权限" tabindex="-1" data-src-line="55" data-src-file="redis/04-operations/chapter-08-pitfalls.md">网络与权限 <a class="header-anchor" href="#网络与权限" aria-label="Permalink to &quot;网络与权限&quot;">​</a></h3><ul data-src-line="57" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="57" data-src-file="redis/04-operations/chapter-08-pitfalls.md">Redis 只监听回环或私网地址，端口不对公网和不可信容器开放。</li><li data-src-line="58" data-src-file="redis/04-operations/chapter-08-pitfalls.md">防火墙或安全组只允许应用与运维网段访问。</li><li data-src-line="59" data-src-file="redis/04-operations/chapter-08-pitfalls.md">每个应用使用独立 ACL 用户，命令和 Key 模式符合最小权限。</li><li data-src-line="60" data-src-file="redis/04-operations/chapter-08-pitfalls.md">密钥通过环境变量或密钥管理系统注入，日志和仓库中没有凭据。</li><li data-src-line="61" data-src-file="redis/04-operations/chapter-08-pitfalls.md">跨不可信网络时启用 TLS，并验证证书、主机名和轮换流程。</li><li data-src-line="62" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><code>rename-command</code> 如有使用，只作为减少误操作的补充措施。</li></ul><p data-src-line="64" data-src-file="redis/04-operations/chapter-08-pitfalls.md">网络、ACL、TLS 和凭据轮换见<a href="./chapter-02-security-access.html">安全与访问控制</a>，部署入口见<a href="./../05-practice/chapter-03-first-production.html">首次生产部署</a>。</p><h2 id="检查可观测性" tabindex="-1" data-src-line="66" data-src-file="redis/04-operations/chapter-08-pitfalls.md">检查可观测性 <a class="header-anchor" href="#检查可观测性" aria-label="Permalink to &quot;检查可观测性&quot;">​</a></h2><ul data-src-line="68" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="68" data-src-file="redis/04-operations/chapter-08-pitfalls.md">延迟使用分位数和慢日志观察，不仅看平均值。</li><li data-src-line="69" data-src-file="redis/04-operations/chapter-08-pitfalls.md">监控 QPS、网络带宽、连接数、命中率、复制延迟和持久化状态。</li><li data-src-line="70" data-src-file="redis/04-operations/chapter-08-pitfalls.md">每个告警都有负责人、阈值依据、处理步骤和升级条件。</li><li data-src-line="71" data-src-file="redis/04-operations/chapter-08-pitfalls.md">能按实例、Key 前缀或客户端定位流量突增，不只保留聚合曲线。</li><li data-src-line="72" data-src-file="redis/04-operations/chapter-08-pitfalls.md">已建立正常负载基线，容量评估来自真实数据而不是示例值。</li></ul><p data-src-line="74" data-src-file="redis/04-operations/chapter-08-pitfalls.md">指标定义和告警设计见<a href="./chapter-06-monitoring.html">监控告警</a>。</p><h2 id="检查集群约束" tabindex="-1" data-src-line="76" data-src-file="redis/04-operations/chapter-08-pitfalls.md">检查集群约束 <a class="header-anchor" href="#检查集群约束" aria-label="Permalink to &quot;检查集群约束&quot;">​</a></h2><ul data-src-line="78" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><li data-src-line="78" data-src-file="redis/04-operations/chapter-08-pitfalls.md">跨槽多 Key 操作已经消除，或通过哈希标签将相关 Key 放入同一槽。</li><li data-src-line="79" data-src-file="redis/04-operations/chapter-08-pitfalls.md">Key 分布不会长期集中到单个主节点，迁移前后都检查槽分布。</li><li data-src-line="80" data-src-file="redis/04-operations/chapter-08-pitfalls.md">大 Key 在扩缩容前已拆分，迁移窗口经过压测。</li><li data-src-line="81" data-src-file="redis/04-operations/chapter-08-pitfalls.md">客户端正确处理 <code>MOVED</code>、<code>ASK</code> 和拓扑刷新，不在异常后无限重定向。</li></ul><p data-src-line="83" data-src-file="redis/04-operations/chapter-08-pitfalls.md">集群机制见<a href="./../03-high-availability/chapter-04-cluster.html">集群模式</a>。</p><h2 id="记录上线结论" tabindex="-1" data-src-line="85" data-src-file="redis/04-operations/chapter-08-pitfalls.md">记录上线结论 <a class="header-anchor" href="#记录上线结论" aria-label="Permalink to &quot;记录上线结论&quot;">​</a></h2><table tabindex="0"><thead data-src-line="87" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><tr data-src-line="87" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><th style="text-align:left;">类别</th><th style="text-align:left;">通过条件</th><th style="text-align:left;">结果</th></tr></thead><tbody data-src-line="89" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><tr data-src-line="89" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">容量</td><td style="text-align:left;">数据增长、内存、磁盘和带宽均有余量</td><td style="text-align:left;">□</td></tr><tr data-src-line="90" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">性能</td><td style="text-align:left;">峰值负载下延迟和错误率达到业务目标</td><td style="text-align:left;">□</td></tr><tr data-src-line="91" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">数据</td><td style="text-align:left;">RPO、RTO、备份和恢复演练已有记录</td><td style="text-align:left;">□</td></tr><tr data-src-line="92" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">高可用</td><td style="text-align:left;">故障转移和客户端拓扑刷新经过验证</td><td style="text-align:left;">□</td></tr><tr data-src-line="93" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">安全</td><td style="text-align:left;">网络、ACL、TLS 和密钥注入检查完成</td><td style="text-align:left;">□</td></tr><tr data-src-line="94" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">告警</td><td style="text-align:left;">核心指标有阈值、负责人和处理步骤</td><td style="text-align:left;">□</td></tr><tr data-src-line="95" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">回滚</td><td style="text-align:left;">配置变更、版本升级和流量回退方案明确</td><td style="text-align:left;">□</td></tr><tr data-src-line="96" data-src-file="redis/04-operations/chapter-08-pitfalls.md"><td style="text-align:left;">降级</td><td style="text-align:left;">Redis 不可用时应用行为符合预期</td><td style="text-align:left;">□</td></tr></tbody></table><p data-src-line="98" data-src-file="redis/04-operations/chapter-08-pitfalls.md">任何一项无法确认时，应记录风险、责任人和截止时间；不要用“默认配置可用”代替验证结果。</p>',31)])])}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
